public class PaymentService implements InitializingBean {
    public PaymentService() {
        System.out.println("constructor");
    }

    @PostConstruct
    public void init() {
        System.out.println("postConstruct");
    }

    @Override
    public void afterPropertiesSet() {
        System.out.println("afterPropertiesSet");
    }

    public void start() {
        System.out.println("start");
    }
}

@Configuration
public class AppConfig {
    @Bean(initMethod = "start")
    public PaymentService paymentService() {
        return new PaymentService();
    }
}

public class Main {
    public static void main(String[] args) {
        new AnnotationConfigApplicationContext(AppConfig.class);
        System.out.println("ready");
    }
}

@Component
@Scope("prototype")
public class CartService implements BeanNameAware, ApplicationContextAware {
    Map<Integer, String> mp;

    public CartService() {
        mp = new HashMap<>();
        System.out.println("CartService constructor called");
    }
    @Override
    public void setBeanName(String name) {
        System.out.println("Bean name is " + name);
    }
    @Override
    public void setApplicationContext(ApplicationContext ctx) {
        System.out.println("Context: " + ctx.getClass().getSimpleName());
    }
    @PostConstruct
    public void start2() {
        System.out.println("Bean is Ready");
        mp.put(1, "Aditya");
        mp.put(2, "Rohit");
    }
    public String getValue(int key) { return mp.get(key); }

    @PreDestroy
    public void stop() {
        mp.clear();
        System.out.println("Bean is getting destroyed");
    }
}

public class Main {
    public static void main(String[] args) {
        ConfigurableApplicationContext context =
                new AnnotationConfigApplicationContext(AppConfig.class);
        CartService cart = context.getBean(CartService.class);
        System.out.println(cart.getValue(1));
        context.close();
    }
}

@Component
public class A {
    B b;

    public A(B b) {
        this.b = b;
    }

    @PostConstruct
    public void setB() {
        b.setA(this);
    }
}

@Component
public class B {
    A a;

    public void setA(A a) {
        this.a = a;
    }
}

public class Main {
    public static void main(String[] args) {
        ApplicationContext context = new AnnotationConfigApplicationContext(AppConfig.class);
        A a = context.getBean(A.class);
        B b = context.getBean(B.class);
        System.out.println(b.a == a);
    }
}
